$:set -euo pipefail
node <<'NODE'
const fs=require('fs'), cp=require('child_process'), crypto=require('crypto');
const base='workspaces/codespace-mcp-srs-design/local-terminals/';
const before=base+'prompts/agent-command-templates.json';
const after=base+'templates/agent-command-templates.json';
for(const p of ['AGENTS.md','terminals_requirements.json','workspaces/codespace-mcp-srs-design/AGENTS.md','workspaces/codespace-mcp-srs-design/README.md',before]){
 if(!fs.existsSync(p))throw Error('Required governing or target file missing: '+p);
 fs.readFileSync(p,'utf8');
}
const rules=fs.readFileSync('AGENTS.md','utf8');
if(!rules.includes('DISCOVERY-04')||!rules.includes('VERIFICATION-02'))throw Error('Expected repository execution contract missing');
const policy=JSON.parse(fs.readFileSync('terminals_requirements.json','utf8'));
if(!policy.requirements.some(x=>x.id==='SRS-001'))throw Error('Expected repository requirements missing');
const local=JSON.parse(fs.readFileSync(before,'utf8'));
if(local.path!==before||local.version!=='1.0.0')throw Error('Unexpected template contents');
if(fs.existsSync(after))throw Error('Destination already exists');
const oldEntries=fs.readdirSync(base+'prompts');
if(oldEntries.length!==1||oldEntries[0]!=='agent-command-templates.json')throw Error('Unexpected additional files in prompts: '+oldEntries.join(','));
const proposed={...local,path:after};
const content=JSON.stringify(proposed,null,2)+'\n';
const api=(args,input)=>JSON.parse(cp.execFileSync('gh',['api',...args],{encoding:'utf8',input}));
const read=(p)=>api(['repos/BestNameYet/Terminals/contents/'+p]);
const origin=read(before);
const originText=Buffer.from(origin.content.replace(/\s/g,''),'base64').toString('utf8');
if(originText!==fs.readFileSync(before,'utf8'))throw Error('Local target does not match remote');
let created=false;
try {
 const made=api(['-X','PUT','repos/BestNameYet/Terminals/contents/'+after,'--input','-'],JSON.stringify({message:'refactor(local-terminals): rename prompts directory to templates',branch:'main',content:Buffer.from(content).toString('base64')}));
 created=true;
 const newContent=read(after);
 if(Buffer.from(newContent.content.replace(/\s/g,''),'base64').toString('utf8')!==content)throw Error('New path readback mismatch; old path retained');
 const removed=api(['-X','DELETE','repos/BestNameYet/Terminals/contents/'+before,'--input','-'],JSON.stringify({message:'refactor(local-terminals): remove former prompts catalog path',branch:'main',sha:origin.sha}));
 let oldAbsent=false;
 try{read(before);}catch(e){oldAbsent=String(e.stderr||e.message).includes('404')||String(e.message).includes('Not Found');}
 if(!oldAbsent)throw Error('Old path not confirmed absent');
 const finalRead=read(after);
 if(Buffer.from(finalRead.content.replace(/\s/g,''),'base64').toString('utf8')!==content)throw Error('Final readback mismatch');
 console.log(JSON.stringify({renamed_from:before,renamed_to:after,create_commit:made.commit.sha,delete_commit:removed.commit.sha,sha256:crypto.createHash('sha256').update(content).digest('hex'),old_path_absent:oldAbsent,readback_verified:true}));
}catch(err){
 console.error('Rename incomplete; new path created='+created+'; '+err.message);
 process.exit(1);
}
